escenas.Mundo:
// Mundo compartido: «Tu inodoro se rellena solo». Baño-maqueta en corte, inodoro de perfil con el
// frente del tanque abierto (tanque a la izquierda contra la pared, taza a la derecha).
// paso 0: tanque lleno con tapa, aleta roja sobre el desagüe, todo en marcha.
// paso 1: igual (la escena 1 quita la tapa).
// paso 2-3: tapa apoyada a un lado contra la pared; tanque destapado.
// paso 4: aleta roja deformada, fuga constante por el conducto hacia la taza.
// paso 5: + ciclo de relleno (la válvula suelta un chorro intermitente).
// paso 6: + agua del tanque teñida con colorante; taza clara.
// paso 7: + taza teñida (fuga confirmada).
// paso 8: llave de paso cerrada, tanque vacío, aleta vieja a la vista.
// paso 9: aleta vieja retirada, cadena suelta colgando, desagüe descubierto.
// paso 10: aleta verde nueva, cadena floja; llave aún cerrada, tanque vacío.
// paso 11: llave abierta, tanque lleno y quieto, taza clara: reparado.
import React from 'react';
import * as THREE from 'three';
import {Pieza, Linea, Brillo} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Recorte, Sombra, Planta, PiezaGeo, Efecto, Tuberia, ESTILO25D} from '../lib25d';

export const PARTES = [
  'inodoro', 'tanque', 'tapa', 'agua', 'aguataza', 'aleta', 'aletanueva', 'cadena',
  'flotador', 'valvula', 'rebose', 'desague', 'palanca', 'llave', 'tubo', 'fuga',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

// ---------- colores y medidas ----------
const BLANCO = '#FBF8F1';
const CROMO = '#C9CED6';
const GRIS = '#8E979F';
const GRIS_OSC = '#5F666E';
const ROJO = '#D6452E';
const VERDE = '#3FAE5A';
const COBRE = '#C8783E';
const MADERA = '#B98552';
const AZULEJO = '#EFE6D6';
const JUNTA = '#D6C8B0';
const AGUA = '#5DBBEE';
const TENIDA = '#2338B5';
const FPS = 30;
const O: V3 = [0.1, 0.08, 0]; // todo el baño va sobre la tarima (y = 0.08)
const Z = -0.15; // plano medio del tanque
const FONDO_T = 1.0; // fondo interior del tanque (local)
const ALTO_AGUA = 0.6;

const EnMundo: React.FC<{children: React.ReactNode}> = ({children}) => <group position={O}>{children}</group>;
const res = (p: ParteProps, color: string) => (p.resaltado ? p.paleta.acentos[2] : color);

// ---------- estados por paso (las escenas animan entre uno y otro) ----------
export const nivelTanque = (paso: number) => (paso >= 8 && paso <= 10 ? 0.03 : 0.8);
export const superficie = (nivel: number) => FONDO_T + ALTO_AGUA * nivel;
export const anguloFlotador = (nivel: number) =>
  Math.min(0.9, Math.max(0.05, Math.asin(Math.min(1, Math.max(-1, (1.5 - superficie(nivel) + 0.01) / 0.16)))));
export const giroLlave = (paso: number) => (paso >= 8 && paso <= 10 ? Math.PI / 2 : 0); // 0 abierta, PI/2 cerrada
export const llaveAbierta = (paso: number) => giroLlave(paso) === 0;
export const tanqueTenido = (paso: number) => paso === 6 || paso === 7;
export const tazaTenida = (paso: number) => paso === 7;
export const hayFuga = (paso: number) => paso >= 4 && paso <= 7;
export const aletaDeformada = (paso: number) => paso >= 4;
export const tapaQuitada = (paso: number) => paso >= 2;
export const modoCadena = (paso: number): 'tensa' | 'suelta' | 'floja' => (paso <= 8 ? 'tensa' : paso === 9 ? 'suelta' : 'floja');

// Puntos clave en coordenadas del mundo (para etiquetas y flechas de las escenas).
const w = (p: V3): V3 => [p[0] + O[0], p[1] + O[1], p[2] + O[2]];
export const PUNTOS = {
  aleta: w([-0.6, 1.05, Z]),
  desague: w([-0.6, 1.02, Z]),
  flotador: w([-0.67, 1.47, -0.1]),
  valvula: w([-0.86, 1.48, Z]),
  rebose: w([-0.42, 1.54, Z]),
  palanca: w([-0.27, 1.53, -0.05]),
  llave: w([-1.03, 0.32, -0.06]),
  taza: w([0.2, 0.52, 0]),
  tanque: w([-0.64, 1.3, Z]),
  tapaFuera: w([0.75, 0.28, -0.72]),
};

// ---------- geometría de la taza ----------
const gTaza = new THREE.LatheGeometry(
  ([[0.001, 0], [0.2, 0], [0.2, 0.18], [0.28, 0.3], [0.38, 0.5], [0.42, 0.58], [0.4, 0.61], [0.3, 0.6], [0.24, 0.5], [0.001, 0.5]] as [number, number][]).map(
    ([r, y]) => new THREE.Vector2(r, y),
  ),
  40,
);

// ---------- partes ----------
/** Cuerpo de porcelana: taza, aro, cuerpo trasero y el conducto del tanque a la taza. */
export const Inodoro: React.FC<ParteProps> = (p) => {
  const c = res(p, BLANCO);
  return (
    <EnMundo>
      <Sombra posicion={[-0.25, 0, -0.1]} radio={0.95} />
      <PiezaGeo geometria={gTaza} color={c} posicion={[0.2, 0, 0]} escala={[1.2, 1, 0.95]} />
      <Pieza forma="toro" medidas={[0.34, 0.035]} color={c} posicion={[0.2, 0.63, 0]} rotacion={[Math.PI / 2, 0, 0]} escala={[1.2, 0.95, 1]} />
      <Pieza forma="caja" medidas={[0.5, 0.95, 0.42]} color={c} posicion={[-0.6, 0.475, Z]} />
      <Pieza forma="caja" medidas={[0.45, 0.3, 0.4]} color={c} posicion={[-0.2, 0.42, Z]} />
      <Pieza forma="caja" medidas={[1.0, 0.06, 0.44]} color={c} posicion={[-0.35, 0.03, Z]} />
      {/* conducto del tanque a la taza, visible en el corte */}
      <Linea desde={[-0.6, 0.95, 0.07]} hasta={[-0.6, 0.64, 0.07]} grosor={0.03} color={JUNTA} />
      <Linea desde={[-0.6, 0.64, 0.07]} hasta={[-0.2, 0.62, 0.07]} grosor={0.03} color={JUNTA} />
      <Linea desde={[-0.2, 0.62, 0.07]} hasta={[-0.04, 0.55, 0.02]} grosor={0.03} color={JUNTA} />
    </EnMundo>
  );
};

/** Paredes del tanque (sin la delantera: vista en corte). */
export const Tanque: React.FC<ParteProps> = (p) => {
  const c = res(p, BLANCO);
  return (
    <EnMundo>
      <Pieza forma="caja" medidas={[0.62, 0.66, 0.05]} color={c} posicion={[-0.64, 1.28, -0.385]} />
      <Pieza forma="caja" medidas={[0.05, 0.66, 0.5]} color={c} posicion={[-0.925, 1.28, Z]} />
      <Pieza forma="caja" medidas={[0.05, 0.66, 0.5]} color={c} posicion={[-0.355, 1.28, Z]} />
      <Pieza forma="caja" medidas={[0.62, 0.05, 0.5]} color={c} posicion={[-0.64, 0.975, Z]} />
    </EnMundo>
  );
};

/** Tapa del tanque: encima (quitada = false) o apoyada contra la pared a la derecha. */
export const Tapa: React.FC<ParteProps & {quitada?: boolean}> = ({quitada = false, ...p}) => (
  <EnMundo>
    {quitada ? (
      <group>
        <Sombra posicion={[0.75, 0, -0.62]} radio={0.4} />
        <Pieza forma="caja" medidas={[0.68, 0.06, 0.56]} color={res(p, BLANCO)} posicion={[0.75, 0.28, -0.74]} rotacion={[-Math.PI / 2 + 0.12, 0, 0]} />
      </group>
    ) : (
      <Pieza forma="caja" medidas={[0.68, 0.06, 0.56]} color={res(p, BLANCO)} posicion={[-0.64, 1.64, Z]} />
    )}
  </EnMundo>
);

/** Agua del tanque en 2D (capa trasera + velo delantero para que las piezas se vean sumergidas). */
export const Agua: React.FC<ParteProps & {nivel?: number; tenida?: boolean; fuga?: boolean}> = ({nivel = 0.8, tenida = false, fuga = false, ...p}) => {
  if (nivel <= 0.001) return null;
  const colores = {...ESTILO25D.colores, agua: res(p, tenida ? TENIDA : AGUA)};
  const op = {nivel, fuga: fuga ? ([0.57, 0.06] as [number, number]) : null, fuerza: fuga ? 0.8 : 0, c: colores};
  return (
    <EnMundo>
      <Recorte dibujo="agua" ancho={0.56} alto={ALTO_AGUA} posicion={[-0.64, FONDO_T + ALTO_AGUA / 2, -0.33]} opciones={op} frame={p.frame ?? 0} fps={FPS} />
      <Recorte dibujo="agua" ancho={0.56} alto={ALTO_AGUA} posicion={[-0.64, FONDO_T + ALTO_AGUA / 2, 0.07]} opciones={op} opacidad={0.28} frame={p.frame ?? 0} fps={FPS} />
    </EnMundo>
  );
};

/** Agua quieta al fondo de la taza (clara o teñida). */
export const AguaTaza: React.FC<ParteProps & {tenida?: boolean}> = ({tenida = false, ...p}) => (
  <EnMundo>
    <mesh position={[0.2, 0.505, 0]} rotation={[-Math.PI / 2, 0, 0]} scale={[1.2, 0.95, 1]}>
      <circleGeometry args={[0.245, 40]} />
      <meshBasicMaterial color={res(p, tenida ? TENIDA : AGUA)} toneMapped={false} />
    </mesh>
  </EnMundo>
);

/** Asiento de la válvula de descarga con el hueco (desagüe) por donde baja el agua. */
export const Desague: React.FC<ParteProps> = (p) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.08, 0.09, 0.04]} color={res(p, GRIS)} posicion={[-0.6, 1.02, Z]} />
    <Pieza forma="cilindro" medidas={[0.058, 0.058, 0.006]} color="#2E3338" posicion={[-0.6, 1.042, Z]} contorno={false} />
  </EnMundo>
);

/** Tubo de rebose con los dos pasadores (ganchitos) donde se enganchan las orejas de la aleta. */
export const Rebose: React.FC<ParteProps> = (p) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.54]} color={res(p, CROMO)} posicion={[-0.42, 1.27, Z]} />
    <Pieza forma="toro" medidas={[0.03, 0.008]} color={res(p, GRIS)} posicion={[-0.42, 1.54, Z]} rotacion={[Math.PI / 2, 0, 0]} />
    <Pieza forma="caja" medidas={[0.04, 0.03, 0.14]} color={res(p, GRIS_OSC)} posicion={[-0.45, 1.045, Z]} />
  </EnMundo>
);

/** Forma común de la aleta: disco cónico de goma con capucha y brazo a los pasadores. */
const FormaAleta: React.FC<{color: string; inclinacion: number; torcida: boolean; tiembla: number}> = ({color, inclinacion, torcida, tiembla}) => (
  <group position={[-0.47, 1.045, Z]} rotation={[torcida ? 0.12 : 0, 0, inclinacion + tiembla]}>
    <group position={[-0.13, 0.0, 0]} scale={torcida ? [1.08, 0.8, 0.9] : 1}>
      <Pieza forma="cilindro" medidas={[0.085, 0.072, 0.035]} color={color} />
      <Pieza forma="media_esfera" medidas={[0.055]} color={color} posicion={[0, 0.017, 0]} escala={[1, 0.55, 1]} />
      <Pieza forma="toro" medidas={[0.013, 0.004]} color={GRIS_OSC} posicion={[0, 0.05, 0]} />
    </group>
    <Pieza forma="caja" medidas={[0.09, 0.02, 0.1]} color={color} posicion={[-0.04, 0.005, 0]} />
  </group>
);

/** Aleta vieja (roja). deformada: torcida y levantada en el borde, deja pasar el agua. */
export const Aleta: React.FC<ParteProps & {deformada?: boolean}> = ({deformada = false, ...p}) => {
  const tiembla = deformada ? Math.sin((p.frame ?? 0) * 0.9) * 0.015 : 0;
  return (
    <EnMundo>
      <FormaAleta color={res(p, deformada ? '#B9392A' : ROJO)} inclinacion={deformada ? -0.16 : 0} torcida={deformada} tiembla={tiembla} />
    </EnMundo>
  );
};

/** Aleta nueva (verde), plana y sellando. */
export const AletaNueva: React.FC<ParteProps> = (p) => (
  <EnMundo>
    <FormaAleta color={res(p, VERDE)} inclinacion={0} torcida={false} tiembla={0} />
  </EnMundo>
);

/** Palanca: manija cromada por fuera del tanque y brazo por dentro. bajada 0..1 la acciona. */
export const Palanca: React.FC<ParteProps & {bajada?: number}> = ({bajada = 0, ...p}) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.02]} color={res(p, CROMO)} posicion={[-0.325, 1.53, -0.05]} rotacion={[0, 0, Math.PI / 2]} />
    <group position={[-0.33, 1.53, -0.08]} rotation={[0, 0, -0.5 * bajada]}>
      <Pieza forma="caja" medidas={[0.12, 0.035, 0.05]} color={res(p, CROMO)} posicion={[0.07, 0, 0.03]} />
      <Pieza forma="caja" medidas={[0.25, 0.02, 0.02]} color={res(p, GRIS)} posicion={[-0.125, 0, -0.04]} />
    </group>
  </EnMundo>
);

/** Cadena de eslabones del brazo de la palanca a la aleta. */
export const Cadena: React.FC<ParteProps & {modo?: 'tensa' | 'suelta' | 'floja'}> = ({modo = 'tensa', ...p}) => {
  const a: V3 = [-0.585, 1.515, -0.12];
  const b: V3 = modo === 'suelta' ? [-0.57, 1.2, -0.12] : [-0.6, 1.1, Z];
  const n = modo === 'floja' ? 13 : modo === 'suelta' ? 9 : 11;
  const vaiven = modo === 'suelta' ? Math.sin((p.frame ?? 0) / 14) * 0.02 : 0;
  return (
    <EnMundo>
      {Array.from({length: n}, (_, i) => {
        const t = i / (n - 1);
        const comba = modo === 'floja' ? 0.06 * Math.sin(Math.PI * t) : vaiven * t;
        const pos: V3 = [a[0] + (b[0] - a[0]) * t + comba, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
        return <Pieza key={i} forma="toro" medidas={[0.013, 0.004]} color={res(p, CROMO)} posicion={pos} rotacion={[0, i % 2 ? Math.PI / 2 : 0, 0]} escala={[1, 1.5, 1]} />;
      })}
    </EnMundo>
  );
};

/** Válvula de llenado con su tubito de relleno hacia el rebose. chorro 0..1: agua que entra. */
export const Valvula: React.FC<ParteProps & {chorro?: number}> = ({chorro = 0, ...p}) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.1]} color={res(p, GRIS_OSC)} posicion={[-0.86, 0.93, Z]} />
    <Pieza forma="cilindro" medidas={[0.035, 0.042, 0.46]} color={res(p, GRIS_OSC)} posicion={[-0.86, 1.23, Z]} />
    <Pieza forma="cilindro" medidas={[0.058, 0.058, 0.07]} color={res(p, GRIS)} posicion={[-0.86, 1.48, Z]} />
    <Linea desde={[-0.82, 1.5, -0.13]} hasta={[-0.62, 1.585, -0.13]} grosor={0.008} color="#34343A" />
    <Linea desde={[-0.62, 1.585, -0.13]} hasta={[-0.42, 1.55, -0.13]} grosor={0.008} color="#34343A" />
    {chorro > 0.02 ? <Efecto tipo="chorro" posicion={[-0.86, 1.28, -0.05]} tam={0.16} fuerza={chorro} frame={p.frame ?? 0} fps={FPS} /> : null}
  </EnMundo>
);

/** Flotador gris en su brazo: baja con el agua y abre la válvula. nivel = nivel del tanque. */
export const Flotador: React.FC<ParteProps & {nivel?: number}> = ({nivel = 0.8, ...p}) => {
  const vaiven = nivel > 0.1 ? Math.sin((p.frame ?? 0) / 18) * 0.015 : 0;
  return (
    <EnMundo>
      <group position={[-0.83, 1.5, -0.1]} rotation={[0, 0, -anguloFlotador(nivel) + vaiven]}>
        <Pieza forma="caja" medidas={[0.13, 0.016, 0.016]} color={res(p, GRIS_OSC)} posicion={[0.065, 0, 0]} />
        <Pieza forma="esfera" medidas={[0.05]} color={res(p, '#A7AFB8')} posicion={[0.16, 0, 0]} />
      </group>
    </EnMundo>
  );
};

/** Llave de paso junto a la pared, con manija naranja. giro 0 = abierta, PI/2 = cerrada. */
export const Llave: React.FC<ParteProps & {giro?: number}> = ({giro = 0, ...p}) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.04, 0.04, 0.1]} color={res(p, CROMO)} posicion={[-1.03, 0.32, -0.1]} rotacion={[0, 0, Math.PI / 2]} />
    <Pieza forma="cilindro" medidas={[0.015, 0.015, 0.06]} color={res(p, CROMO)} posicion={[-1.03, 0.32, -0.05]} rotacion={[Math.PI / 2, 0, 0]} />
    <group position={[-1.03, 0.32, -0.015]} rotation={[0, 0, giro]}>
      <Pieza forma="caja" medidas={[0.17, 0.045, 0.025]} color={res(p, p.paleta.acentos[0])} />
    </group>
  </EnMundo>
);

/** Tubería: cobre dentro de la pared (en corte) y manguera flexible de la llave al tanque. */
export const Tubo: React.FC<ParteProps & {flujo?: number}> = ({flujo = 0, ...p}) => (
  <EnMundo>
    <Pieza forma="cilindro" medidas={[0.022, 0.022, 0.32]} color={res(p, COBRE)} posicion={[-1.22, 0.16, -0.1]} />
    <Pieza forma="esfera" medidas={[0.03]} color={res(p, COBRE)} posicion={[-1.22, 0.32, -0.1]} />
    <Pieza forma="cilindro" medidas={[0.022, 0.022, 0.16]} color={res(p, COBRE)} posicion={[-1.14, 0.32, -0.1]} rotacion={[0, 0, Math.PI / 2]} />
    <Tuberia puntos={[[-1.0, 0.33, -0.1], [-1.0, 0.86, -0.1], [-0.86, 0.88, Z]]} radio={0.016} color={res(p, '#D8DDE3')} flujo={flujo} frame={p.frame ?? 0} fps={FPS} />
  </EnMundo>
);

/** Fuga: gotas que bajan del desagüe por el conducto y ondas en la taza. */
export const Fuga: React.FC<ParteProps> = (p) => {
  const f = p.frame ?? 0;
  const ruta: V3[] = [[-0.6, 1.0, Z], [-0.6, 0.95, 0.09], [-0.6, 0.64, 0.09], [-0.2, 0.62, 0.09], [-0.04, 0.55, 0.04]];
  const en = (u: number): V3 => {
    const s = u * (ruta.length - 1);
    const i = Math.min(ruta.length - 2, Math.floor(s));
    const k = s - i;
    return [0, 1, 2].map((j) => ruta[i][j] + (ruta[i + 1][j] - ruta[i][j]) * k) as V3;
  };
  const color = res(p, AGUA);
  return (
    <EnMundo>
      {[0, 1, 2, 3, 4, 5].map((i) => (
        <Brillo key={i} posicion={en((((f / 40 + i / 6) % 1) + 1) % 1)} color={color} radio={0.022} />
      ))}
      <Efecto tipo="ondas" posicion={[0.12, 0.51, 0.02]} rotacion={[-Math.PI / 2, 0, 0]} tam={0.36} color={color} frame={f} fps={FPS} />
    </EnMundo>
  );
};

// ---------- el baño (fondo fijo) ----------
const Bano: React.FC<{frame: number}> = ({frame}) => (
  <EnMundo>
    {/* tarima de azulejo */}
    <Pieza forma="caja" medidas={[2.5, 0.08, 1.7]} color="#E4D8C3" posicion={[-0.1, -0.04, 0.0]} />
    <Pieza forma="caja" medidas={[2.52, 0.03, 0.03]} color="#C89B6D" posicion={[-0.1, -0.065, 0.85]} />
    {[-0.6, 0.0, 0.6].map((x) => (
      <Pieza key={x} forma="caja" medidas={[0.012, 0.002, 1.6]} color={JUNTA} posicion={[x, 0.001, 0]} contorno={false} />
