    {/* pared del fondo: azulejo abajo, pintura arriba, ventana con luz */}
    <Pieza forma="caja" medidas={[2.5, 1.15, 0.08]} color={AZULEJO} posicion={[-0.1, 0.575, -0.86]} />
    <Pieza forma="caja" medidas={[2.5, 0.7, 0.07]} color="#F6E7CC" posicion={[-0.1, 1.5, -0.865]} />
    <Pieza forma="caja" medidas={[2.52, 0.05, 0.1]} color={MADERA} posicion={[-0.1, 1.15, -0.85]} />
    {[0.3, 0.6, 0.9].map((y) => (
      <Pieza key={y} forma="caja" medidas={[2.5, 0.012, 0.01]} color={JUNTA} posicion={[-0.1, y, -0.815]} contorno={false} />
    ))}
    {[-0.8, -0.4, 0.0, 0.4, 0.8].map((x) => (
      <Pieza key={x} forma="caja" medidas={[0.012, 1.12, 0.01]} color={JUNTA} posicion={[x, 0.56, -0.815]} contorno={false} />
    ))}
    <Pieza forma="caja" medidas={[0.62, 0.48, 0.05]} color={MADERA} posicion={[0.45, 1.52, -0.82]} />
    <Pieza forma="caja" medidas={[0.52, 0.38, 0.03]} color="#FFF3D6" brillo="#FFE6B0" posicion={[0.45, 1.52, -0.8]} />
    <Pieza forma="caja" medidas={[0.02, 0.38, 0.04]} color={MADERA} posicion={[0.45, 1.52, -0.79]} />
    <Pieza forma="caja" medidas={[0.52, 0.02, 0.04]} color={MADERA} posicion={[0.45, 1.52, -0.79]} />
    {/* portarrollos */}
    <Pieza forma="caja" medidas={[0.04, 0.04, 0.08]} color={CROMO} posicion={[0.85, 0.72, -0.78]} />
    <Pieza forma="cilindro" medidas={[0.065, 0.065, 0.12]} color="#FFFFFF" posicion={[0.85, 0.66, -0.72]} rotacion={[0, 0, Math.PI / 2]} />
    {/* pared izquierda con el corte abajo que deja ver el tubo de cobre */}
    <Pieza forma="caja" medidas={[0.12, 1.35, 0.8]} color={AZULEJO} posicion={[-1.22, 1.175, -0.46]} />
    <Pieza forma="caja" medidas={[0.12, 0.5, 0.6]} color={AZULEJO} posicion={[-1.22, 0.25, -0.56]} />
    <Pieza forma="caja" medidas={[0.12, 0.5, 0.02]} color="#9C7A5A" posicion={[-1.22, 0.25, -0.25]} />
    <Pieza forma="caja" medidas={[0.13, 0.05, 0.82]} color={MADERA} posicion={[-1.22, 1.15, -0.45]} />
    {/* planta en la esquina delantera */}
    <Sombra posicion={[1.0, 0, 0.45]} radio={0.25} />
    <Pieza forma="cilindro" medidas={[0.11, 0.08, 0.16]} color={MADERA} posicion={[1.0, 0.08, 0.45]} />
    <Planta posicion={[1.0, 0.14, 0.46]} alto={0.42} frame={frame} fps={FPS} />
  </EnMundo>
);

// ---------- mundo completo ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const ver = (n: string) => !ocultar.includes(n);
  const r = (n: string) => resaltar.includes(n);
  const nivel = nivelTanque(paso);
  const chorro = paso >= 5 && paso <= 7 ? Math.max(0, Math.sin(frame / 25)) * 0.5 : 0;
  const base = {paleta, frame};
  return (
    <group>
      <Bano frame={frame} />
      {ver('inodoro') ? <Inodoro {...base} resaltado={r('inodoro')} /> : null}
      {ver('tanque') ? <Tanque {...base} resaltado={r('tanque')} /> : null}
      {ver('tapa') ? <Tapa {...base} resaltado={r('tapa')} quitada={tapaQuitada(paso)} /> : null}
      {ver('aguataza') ? <AguaTaza {...base} resaltado={r('aguataza')} tenida={tazaTenida(paso)} /> : null}
      {ver('desague') ? <Desague {...base} resaltado={r('desague')} /> : null}
      {ver('rebose') ? <Rebose {...base} resaltado={r('rebose')} /> : null}
      {ver('aleta') && paso <= 8 ? <Aleta {...base} resaltado={r('aleta')} deformada={aletaDeformada(paso)} /> : null}
      {ver('aletanueva') && paso >= 10 ? <AletaNueva {...base} resaltado={r('aletanueva')} /> : null}
      {ver('palanca') ? <Palanca {...base} resaltado={r('palanca')} /> : null}
      {ver('cadena') ? <Cadena {...base} resaltado={r('cadena')} modo={modoCadena(paso)} /> : null}
      {ver('valvula') ? <Valvula {...base} resaltado={r('valvula')} chorro={chorro} /> : null}
      {ver('flotador') ? <Flotador {...base} resaltado={r('flotador')} nivel={nivel} /> : null}
      {ver('llave') ? <Llave {...base} resaltado={r('llave')} giro={giroLlave(paso)} /> : null}
      {ver('tubo') ? <Tubo {...base} resaltado={r('tubo')} flujo={chorro > 0.05 ? 1 : 0} /> : null}
      {ver('fuga') && hayFuga(paso) ? <Fuga {...base} resaltado={r('fuga')} /> : null}
      {ver('agua') ? <Agua {...base} resaltado={r('agua')} nivel={nivel} tenida={tanqueTenido(paso)} fuga={hayFuga(paso)} /> : null}
    </group>
  );
};

