import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Flecha, Linea, Aro, caer, aparecer, rebote, flotar, mover, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Sombra, Efecto} from '../lib25d';
import {Mundo, PUNTOS} from './Mundo';

const O: V3 = [0.1, 0.08, 0];
const Z = -0.15;
const BLANCO = '#FBF8F1';
const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
const suave = (frame: number, a: number, b: number) =>
  interpolate(frame, [a, b], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic)});

/** Llave inglesa naranja (la herramienta del plomero que no hace falta). */
const LlaveInglesa: React.FC<{color: string}> = ({color}) => (
  <group>
    <Pieza forma="caja" medidas={[0.42, 0.05, 0.03]} color={color} posicion={[0, 0, 0]} />
    <Pieza forma="caja" medidas={[0.16, 0.06, 0.035]} color="#2B241D" posicion={[-0.14, 0, 0.002]} />
    <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.035]} color={color} posicion={[0.23, 0, 0]} rotacion={[Math.PI / 2, 0, 0]} />
    <Pieza forma="caja" medidas={[0.05, 0.1, 0.035]} color={color} posicion={[0.29, 0.06, 0]} />
    <Pieza forma="caja" medidas={[0.05, 0.08, 0.035]} color="#C9CED6" posicion={[0.29, -0.06, 0]} />
    <Pieza forma="cilindro" medidas={[0.018, 0.018, 0.05]} color="#C9CED6" posicion={[0.2, -0.03, 0]} rotacion={[0, 0, Math.PI / 2]} />
  </group>
);

export const Escena1: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [naranja, , resalte] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tDanado = momento(palabras, fps, 'dañado', 14);
  const tNecesitas = momento(palabras, fps, 'necesitas', 45);
  const tPlomero = momento(palabras, fps, 'plomero', 64);
  const tAbre = momento(palabras, fps, 'abre', 105);
  const tTanque = momento(palabras, fps, 'tanque', 118);
  const tMira = momento(palabras, fps, 'mira', 133);
  const tFondo = momento(palabras, fps, 'fondo', 146);

  // ---- "no está dañado": aro y resalte breve del inodoro ----
  const aroSano = Math.min(aparecer(frame, 2, 14), 1 - aparecer(frame, tDanado + 34, 10));
  const sanoResaltado = frame >= tDanado && frame < tDanado + 36;
  const etiquetaSano = Math.min(aparecer(frame, tDanado, 8), 1 - aparecer(frame, tPlomero - 4, 8));

  // ---- "no necesitas plomero": la llave inglesa cae y sale volando ----
  const cae = caer(frame, fps, tNecesitas, 1.4);
  const vuela = suave(frame, tPlomero, tPlomero + 20);
  const llaveVisible = frame < tPlomero + 22;
  const llavePos: V3 = [0.55 + vuela * 1.6, 0.11 + cae.y + Math.sin(Math.PI * Math.min(1, vuela * 1.3)) * 0.9, 0.6 - vuela * 0.3];
  const llaveEsc = cae.escala * (1 - Math.max(0, vuela - 0.75) * 4);

  // ---- "abre el tanque": la mano levanta la tapa y la apoya en la pared ----
  const tLevanta = tAbre;
  const tSuelta = tLevanta + 37;
  const p = suave(frame, tLevanta, tSuelta);
  const tiembla = frame >= tAbre - 6 && frame < tLevanta + 3 ? Math.sin(frame * 2.2) * 0.02 : 0;
  const ini: V3 = [-0.64, 1.64, Z];
  const fin: V3 = [0.75, 0.28, -0.74];
  const tapaLocal: V3 = [lerp(ini[0], fin[0], p), lerp(ini[1], fin[1], p) + Math.sin(Math.PI * p) * 0.18, lerp(ini[2], fin[2], p)];
  const tapaRot: V3 = [lerp(0, -Math.PI / 2 + 0.12, Math.min(1, p * 1.15)), 0, tiembla + Math.sin(Math.PI * p) * -0.15];
  const tapaMundo: V3 = [tapaLocal[0] + O[0], tapaLocal[1] + O[1], tapaLocal[2] + O[2]];
  const asentada = aparecer(frame, tSuelta - 4, 6);

  // Mano: entra, agarra el borde derecho de la tapa, la lleva, suelta y se va.
  const agarre: V3 = [tapaMundo[0] + 0.28, tapaMundo[1] + 0.1 - p * 0.05, tapaMundo[2] + 0.32 + p * 0.1];
  const entra = suave(frame, tAbre - 14, tLevanta);
  const sale = suave(frame, tSuelta + 2, tSuelta + 16);
  const manoPos: V3 =
    frame < tLevanta
      ? [lerp(1.3, agarre[0], entra), lerp(1.9, agarre[1], entra), agarre[2]]
      : [agarre[0] + sale * 0.9, agarre[1] + sale * 0.9, agarre[2]];
  const manoEsc = Math.min(entra, 1 - sale);
  const manoGiro = -0.25 + Math.sin(Math.PI * p) * 0.2;

  // Resaltes
  const resaltar: string[] = [];
  if (sanoResaltado) resaltar.push('inodoro');
  if (frame >= tTanque && frame < tTanque + 34) resaltar.push('tanque');
  if (frame >= tFondo && frame < 158) resaltar.push('aleta');

  // ---- "mira al fondo": flecha que baja hasta el hueco ----
  const cierre = 1 - aparecer(frame, 151, 7);
  const flecha = Math.min(mover(frame, [tMira, tMira + 12], [0, 1]), cierre);
  const fondoPulso = Math.min(aparecer(frame, tFondo, 8), cierre);
  const bote = rebote(frame, fps, tFondo);
  const des = PUNTOS.desague;

  return (
    <group>
      <Mundo paso={1} frame={frame} fps={fps} paleta={paleta} ocultar={['tapa']} resaltar={resaltar} />

      {/* Tapa animada (al terminar queda igual que en el paso 2) */}
      <group position={O}>
        <Sombra posicion={[0.75, 0, -0.62]} radio={0.4} fuerza={asentada} />
        <Pieza forma="caja" medidas={[0.68, 0.06, 0.56]} color={BLANCO} posicion={tapaLocal} rotacion={tapaRot} />
      </group>
      {/* Mano 2D delante de la tapa */}
      {manoEsc > 0.01 ? (
        <Mano pose="agarra" ancho={0.5} posicion={manoPos} rotacion={[0, 0, manoGiro]} escala={manoEsc} espejo frame={frame} fps={fps} />
      ) : null}
      {/* Gotitas que caen del borde de la tapa al levantarla */}
      {frame > tLevanta && frame < tLevanta + 22 ? (
        <Efecto tipo="gotas" posicion={[tapaMundo[0], tapaMundo[1] - 0.15, tapaMundo[2] + 0.25]} tam={0.25} color="#5DBBEE" frame={frame} fps={fps} />
      ) : null}

      {/* "No está dañado" */}
      <Aro posicion={[-0.15, 0.08, -0.1]} radio={0.95} color={resalte} progreso={aroSano} grosor={0.018} />
      <Etiqueta texto="sin daños" punto={[0.55, 0.55, 0.15]} desplazamiento={[0.3, 0.55, 0.2]} escala={etiquetaSano} />

      {/* "No necesitas plomero": la herramienta cae y sale despedida */}
      {llaveVisible ? (
        <group>
          <Sombra posicion={[0.55, 0.085, 0.6]} radio={0.28} fuerza={cae.escala * (1 - vuela)} />
          <group position={llavePos} rotation={[-Math.PI / 2 + cae.giro, 0, 0.5 + vuela * 9]} scale={Math.max(0.001, llaveEsc)}>
            <LlaveInglesa color={naranja} />
          </group>
        </group>
      ) : null}
      {vuela > 0.02 && vuela < 0.9 ? (
        <Linea desde={[0.55, 0.2, 0.6]} hasta={[llavePos[0] - 0.15, llavePos[1] - 0.05, llavePos[2]]} discontinua grosor={0.008} color="#2B241D" />
      ) : null}

      {/* "Mira al fondo": flecha que baja al desagüe y pulso en el hueco */}
      <Flecha desde={[des[0] + 0.02, 1.95, 0.12]} hasta={[des[0], des[1] + 0.12, des[2] + 0.05]} color={resalte} grosor={0.022} progreso={flecha} />
      <Aro posicion={[des[0], des[1] + 0.02, des[2]]} radio={0.12 + 0.03 * bote + flotar(frame, 0.01, 12)} color={naranja} progreso={fondoPulso} grosor={0.012} />

      {/* Capa delantera: frasco de colorante y repuesto de papel */}
      <group position={[-0.95, 0.08, 0.62]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.12} />
        <Pieza forma="cilindro" medidas={[0.05, 0.055, 0.16]} color="#2338B5" posicion={[0, 0.08, 0]} />
        <Pieza forma="caja" medidas={[0.07, 0.06, 0.01]} color="#E9E1D3" posicion={[0, 0.08, 0.052]} />
        <Pieza forma="cilindro" medidas={[0.025, 0.03, 0.05]} color="#F2C94C" posicion={[0, 0.185, 0]} />
        <Pieza forma="cono" medidas={[0.018, 0.04]} color="#F2C94C" posicion={[0, 0.23, 0]} />
      </group>
      <group position={[-0.7, 0.08, 0.72]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.1} />
        <Pieza forma="cilindro" medidas={[0.065, 0.065, 0.12]} color="#FFFFFF" posicion={[0, 0.06, 0]} />
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.122]} color="#C89B6D" posicion={[0, 0.06, 0]} contorno={false} />
      </group>
    </group>
  );
};
